// Reports are generated by the provider fixture from its actual documents,
// independently of STYK's SQL state or intended publication quantity.
func supersededInventoryProvider(f positionHTTPFixture, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		stock := &nativeMovementHTTPProvider{position: f.provider}
		recorded := httptest.NewRecorder()
		if !stock.stock(recorded, r) {
			next.ServeHTTP(w, r)
			return
		}
		var payload map[string]any
		decoder := json.NewDecoder(recorded.Body)
		decoder.UseNumber()
		if decoder.Decode(&payload) != nil {
			w.WriteHeader(500)
			return
		}
		if strings.HasPrefix(r.URL.Path, "/report/stock/") {
			reserve := supersededNativeReserve(f, strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer synthetic-orders-moysklad-"))
			for _, item := range payload["rows"].([]any) {
				row := item.(map[string]any)
				if r.URL.Path == "/report/stock/all" {
					row["reserve"] = reserve
				} else {
					row["stockByStore"].([]any)[0].(map[string]any)["reserve"] = reserve
				}
			}
		}
		f.provider.base.reply(w, payload)
	})
}

func supersededNativeReserve(f positionHTTPFixture, account string) json.Number {
	base := f.provider.base
	base.mu.Lock()
	defer base.mu.Unlock()
	var total int64
	for _, document := range base.native {
		if document.account != account || document.body["applicable"] != true {
			continue
		}
		for _, position := range document.body["positions"].([]any) {
			row := position.(map[string]any)
			href := row["assortment"].(map[string]any)["meta"].(map[string]any)["href"].(string)
			if !strings.HasSuffix(href, "/"+ordersProcessID(8)) {
				continue
			}
			quantity, err := strconv.ParseInt(row["reserve"].(json.Number).String(), 10, 64)
			if err != nil {
				base.t.Error(err)
				return json.Number("-1")
			}
			total += quantity
		}
	}
	return json.Number(strconv.FormatInt(total, 10))
}

func TestOrdersSupersededSplitInventoryWaitsForActualPointAndFreshTraversal(t *testing.T) {
	f, _, split := supersededSplitHTTPFixture(t)
	preview := f.preview(t)
	if !preview.Decisions[0].Ready || len(preview.Decisions[0].Commands) != 1 {
		t.Fatal("retirement not ready", preview.Decisions[0].Validation)
	}
	f.approve(t, preview)
	f.run(t, orders.StateAcknowledged)
	f.run(t, orders.StateReconciled)
	parent := f.readNative(t)
	completeSupersededSplitChildren(t, f, split, parent.Correlation.CustomerOrderID)
	f.provider.base.server.Config.Handler = supersededInventoryProvider(f, f.provider.base.server.Config.Handler)
	native := nativeMovementHTTPFixture{positionHTTPFixture: f}
	before := nativeDurableStockImport(t, native)
	if guard := nativeAttributionGuard(t, native, before); !guard.Blocked {
		t.Fatal("release receipts fabricated fresh native proof")
	}
	collectNativeAttributionPoint(t, native)
	if guard := nativeAttributionGuard(t, native, before); !guard.Blocked {
		t.Fatal("point read was falsely included in an earlier stock traversal")
	}
	batch := nativeDurableStockImport(t, native)
	guard := nativeAttributionGuard(t, native, batch)
	if guard.Blocked || len(guard.Obligations) != 3 {
		t.Fatalf("fresh native and actual aggregate reserve did not settle split: %+v", guard)
	}
	for _, obligation := range guard.Obligations {
		if obligation.PostingNumber == split.Command.PostingNumber && obligation.State != orderinventory.Superseded {
			t.Fatalf("original parent not explicitly retired: %+v", obligation)
		}
	}
	assertOrdersRowCount(t, f.ordersStoreFixture, `SELECT count(*) FROM orders_native_point_reads WHERE code=''`, 3)
	assertOrdersRowCount(t, f.ordersStoreFixture, `SELECT count(*) FROM moy_order_batches`, 0)
}
